export const STORAGE_KEY = 'biztrack.ledger.v1';
export const CURRENCIES = {XAF:{name:'Central African CFA franc',digits:0},XOF:{name:'West African CFA franc',digits:0},USD:{name:'US dollar',digits:2},EUR:{name:'Euro',digits:2},GBP:{name:'British pound',digits:2},NGN:{name:'Nigerian naira',digits:2},GHS:{name:'Ghanaian cedi',digits:2},KES:{name:'Kenyan shilling',digits:2},ZAR:{name:'South African rand',digits:2}};
export const CATEGORIES = {sale:['Product sales','Services','Other sales'],expense:['Stock & supplies','Transport','Rent & utilities','Marketing','Staff','Equipment','Other expenses']};
export function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
export function emptyLedger(){return {schema:1,app:'BizTrack',businessName:'My business',defaultCurrency:'XAF',entries:[],lastBackup:null};}
export function amountText(value,currency='XAF',group=true){if(!Number.isSafeInteger(value)||!Object.hasOwn(CURRENCIES,currency))throw Error('Invalid currency amount.');const n=BigInt(value),absolute=n<0n?-n:n,digits=CURRENCIES[currency].digits,scale=10n**BigInt(digits),whole=absolute/scale;return `${n<0n?'-':''}${group?whole.toLocaleString('en-GB'):whole.toString()}${digits?'.'+String(absolute%scale).padStart(digits,'0'):''}`;}
export function money(value,currency='XAF'){return `${currency} ${amountText(value,currency)}`;}
export function validDate(s){if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(`${s}T12:00:00Z`);return !Number.isNaN(+d)&&d.toISOString().slice(0,10)===s&&s>='1900-01-01'&&s<='9999-12-31';}
export function toMinor(value,currency){if(typeof currency!=='string'||!Object.hasOwn(CURRENCIES,currency))throw Error('Choose a supported currency.');const digits=CURRENCIES[currency].digits;const s=String(value).trim();if(!new RegExp(`^\\d+(?:\\.\\d{1,${digits||1}})?$`).test(s)||(digits===0&&s.includes('.')))throw Error(digits===0?`${currency} uses whole amounts. Enter a whole number.`:`Use up to ${digits} decimal places.`);const [whole,part='']=s.split('.');const minor=Number(whole)*10**digits+Number(part.padEnd(digits,'0'));if(!Number.isSafeInteger(minor)||minor<=0||minor>99999999999999)throw Error('Enter a positive amount smaller than 100 trillion minor units.');return minor;}
export function validateLedger(input){if(!input||input.app!=='BizTrack'||input.schema!==1||!Array.isArray(input.entries)||input.entries.length>100000)throw Error('This is not a supported BizTrack backup.');if(typeof input.businessName!=='string'||!input.businessName.trim()||input.businessName.length>80||typeof input.defaultCurrency!=='string'||!Object.hasOwn(CURRENCIES,input.defaultCurrency))throw Error('The backup has invalid business preferences.');const ids=new Set();const entries=input.entries.map(e=>{if(!e||typeof e.id!=='string'||!e.id||e.id.length>100||ids.has(e.id)||!['sale','expense'].includes(e.type)||typeof e.currency!=='string'||!Object.hasOwn(CURRENCIES,e.currency)||!Number.isSafeInteger(e.amount)||e.amount<=0||e.amount>99999999999999||!validDate(e.date)||typeof e.description!=='string'||!e.description.trim()||e.description.length>160||!CATEGORIES[e.type].includes(e.category))throw Error('The backup contains an invalid or duplicate transaction. Nothing was changed.');ids.add(e.id);return {id:e.id,type:e.type,currency:e.currency,amount:e.amount,date:e.date,description:e.description.trim(),category:e.category};});return {schema:1,app:'BizTrack',businessName:input.businessName.trim(),defaultCurrency:input.defaultCurrency,entries,lastBackup:typeof input.lastBackup==='string'&&validDate(input.lastBackup)?input.lastBackup:null};}
export function selectEntries(entries,{currency,from='',to='',type='all',search=''}={}){const term=search.trim().toLocaleLowerCase();return entries.map((entry,index)=>({entry,index})).filter(({entry:e})=>(!currency||e.currency===currency)&&(!from||e.date>=from)&&(!to||e.date<=to)&&(type==='all'||type===e.type)&&(!term||`${e.description} ${e.category}`.toLocaleLowerCase().includes(term))).sort((a,b)=>b.entry.date.localeCompare(a.entry.date)||b.index-a.index).map(({entry})=>entry);}
export function backupDue(ledger,date=today()){if(!ledger.entries.length||!validDate(date))return false;const since=validDate(ledger.lastBackup)?ledger.lastBackup:ledger.entries.reduce((old,e)=>e.date<old?e.date:old,date);return Date.parse(date+'T12:00:00Z')-Date.parse(since+'T12:00:00Z')>=7*86400000;}
export function replaceEntry(entries,entry){return entries.some(e=>e.id===entry.id)?entries.map(e=>e.id===entry.id?entry:e):[...entries,entry];}
export function restoreDeletions(entries,deletions){const restored=[...entries];for(const {entry,index} of [...deletions].reverse())if(!restored.some(e=>e.id===entry.id))restored.splice(Math.min(Math.max(0,index),restored.length),0,entry);return restored;}
export function totals(entries){let sales=0,expenses=0,salesCount=0,expenseCount=0;for(const e of entries){if(e.type==='sale'){sales+=e.amount;salesCount++;}else{expenses+=e.amount;expenseCount++;}if(!Number.isSafeInteger(sales)||!Number.isSafeInteger(expenses))throw Error('The ledger total is too large to calculate accurately.');}return {sales,expenses,profit:sales-expenses,salesCount,expenseCount,margin:sales?((sales-expenses)/sales)*100:null};}
export function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
export function csv(entries,currency){const field=x=>{let s=String(x);if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const rows=[['Date','Type','Description','Category','Currency','Sale','Expense']];for(const e of entries){const val=amountText(e.amount,e.currency,false);rows.push([e.date,e.type,e.description,e.category,e.currency,e.type==='sale'?val:'',e.type==='expense'?val:'']);}const t=totals(entries);rows.push([],['TOTAL SALES','','','',currency,amountText(t.sales,currency,false),''],['TOTAL EXPENSES','','','',currency,'',amountText(t.expenses,currency,false)],['NET PROFIT','','','',currency,amountText(t.profit,currency,false),'']);return '\uFEFF'+rows.map(r=>r.map(field).join(',')).join('\r\n');}
export function periodRange(period,month=today().slice(0,7)){if(period==='today')return {from:today(),to:today()};if(period==='all')return {from:'',to:''};const [y,m]=month.split('-').map(Number);return {from:`${month}-01`,to:`${month}-${new Date(y,m,0).getDate()}`};}
export function demoLedger(){const data=emptyLedger();data.businessName='Sample business';const now=today(),month=now.slice(0,7),day=Number(now.slice(-2));const items=[['sale',185000,'Product sales','Weekend orders',0],['expense',28500,'Stock & supplies','Packaging & supplies',0],['sale',95000,'Services','Brand design project',1],['expense',12000,'Transport','Customer deliveries',2],['sale',142000,'Product sales','Shop sales',3],['expense',65000,'Rent & utilities','Workspace rent',4],['sale',78000,'Product sales','Online orders',5],['expense',18500,'Marketing','Social media promotion',6],['sale',210000,'Services','Website project',7],['expense',9500,'Stock & supplies','Printing supplies',8],['sale',125000,'Product sales','Store orders',9],['expense',15000,'Other expenses','Business internet',10]];data.entries=items.map(([type,amount,category,description,offset],i)=>({id:`demo-${String(i).padStart(2,'0')}`,type,amount,category,description,currency:'XAF',date:`${month}-${String(Math.max(1,day-offset)).padStart(2,'0')}`}));return data;}
